macro.command:
// Draught of the Echoing Step
// Effect "Echoing Step" (DAE on / each = start of your turn / off, and isAttacked), the Step reaction (postActiveEffects;
// its damage is the burst against the attacker), and each echo's own isHit: an echo that is hit is gone. Up to three
// echoes at a time; while one is within 5 feet of you, the "Echo Shroud" effect gives attacks against you disadvantage. When an attack
// would hit you, a d6 for each echo within 5 feet: on any 3 or higher an echo takes the hit instead. Step is only to an
// echo more than 5 feet away that you can see. Both are worked out when you are attacked (isAttacked, before hits are
// checked and reactions offered), as one-attack effects. Once a round the step gives your reaction back.
const FLAG = "echoingStep";
const MAX_ECHOES = 3;
const NEAR = 5;
const name = macroItem?.name ?? "Draught of the Echoing Step";
const say = (who, content) => ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: who }), content: `<strong>${name}</strong>: ${content}` });
const effectOf = (a) => a?.effects.find(e => e.getFlag("midi-qol", FLAG) !== undefined);
const shroudOf = (a) => a?.effects.find(e => e.getFlag("midi-qol", "echoShroud"));
const updateEffect = (a, effect, update) => effect && MidiQOL.socket().executeAsGM("updateEffects", { actorUuid: a.uuid, updates: [{ _id: effect.id, ...update }] });
// the drinker's live echoes, oldest first (echo is the single-echo flag of earlier versions)
const echoesOf = (a) => {
  const state = effectOf(a)?.getFlag("midi-qol", FLAG) ?? {};
  return (state.echoes ?? (state.echo ? [state.echo] : [])).filter(uuid => fromUuidSync(uuid));
};
const setEchoes = async (a, echoes) => {
  await updateEffect(a, effectOf(a), { [`flags.midi-qol.${FLAG}.echoes`]: echoes, [`flags.midi-qol.${FLAG}.echo`]: null });
  const shroud = shroudOf(a);
  if (shroud && shroud.disabled !== (echoes.length === 0)) await updateEffect(a, shroud, { disabled: echoes.length === 0 });
};
const removeEcho = async (uuid) => { if (uuid && fromUuidSync(uuid)) await MidiQOL.socket().executeAsGM("deleteToken", { tokenUuid: uuid }); };
// an echo is scenery: never a combatant
const dropEchoCombatants = async () => {
  for (const combat of game.combats) {
    const ids = combat.combatants.filter(c => c.token?.getFlag("midi-qol", "echoOf")).map(c => c.id);
    if (ids.length && combat.canUserModify(game.user, "update")) await combat.deleteEmbeddedDocuments("Combatant", ids);
  }
};

// A new echo where the drinker stands, if there is room for one and none is already there.
async function placeEcho(drinker, drinkerToken) {
  const doc = drinkerToken?.document ?? drinkerToken;
  if (!doc) return;
  await dropEchoCombatants();
  const echoes = echoesOf(drinker);
  if (echoes.length >= MAX_ECHOES) return;
  if (echoes.some(uuid => { const e = fromUuidSync(uuid); return e?.x === doc.x && e?.y === doc.y; })) return;
  const data = doc.toObject();
  delete data._id;
  // the echo is an unlinked copy: drop the effects it would inherit from the drinker's actor (Echoing Step among them)
  const inherited = (game.actors.get(doc.actorId)?.effects ?? []).map(e => ({ _id: e.id, _tombstone: true }));
  // under the drinker, so clicking the shared space picks the drinker
  Object.assign(data, { name: `Echo of ${doc.name}`, alpha: 0.5, actorLink: false, hidden: false, sort: (doc.sort ?? 0) - 1 });
  foundry.utils.setProperty(data, "sight.enabled", false);
  foundry.utils.setProperty(data, "flags.midi-qol.echoOf", drinker.uuid);
  // an image: no actions or reactions of its own (it is a copy of the drinker, items and all); an echo that is hit disappears
  data.delta = { flags: { "midi-qol": { isEcho: true } }, effects: [...inherited, { name: "Echo", img: macroItem?.img ?? "icons/svg/aura.svg", transfer: false,
    statuses: ["incapacitated"],
    system: { changes: [{ key: "flags.midi-qol.onUseMacroName", type: "custom", value: `ItemMacro.${macroItem.uuid}, isHit` }] } }] };
  const created = await DAE.createToken(data, doc.x, doc.y);
  const id = created?.[0]?._id;
  if (id) await setEchoes(drinker, [...echoes, `${doc.parent.uuid}.Token.${id}`]);
}

const pass = args[0]?.macroPass;
// echoes made before their inherited effects were dropped still carry Echoing Step: they never act as the drinker
const isEcho = !!(actor?.getFlag("midi-qol", "isEcho") || (token?.document ?? token)?.getFlag?.("midi-qol", "echoOf"));
if (["on", "each", "off"].includes(args[0]) && isEcho) return;
if (args[0] === "on" || args[0] === "each") return placeEcho(actor, token);

if (args[0] === "off") {
  const state = args.at(-1)?.efData?.flags?.["midi-qol"]?.[FLAG] ?? {};
  const echoes = (state.echoes ?? (state.echo ? [state.echo] : [])).filter(uuid => fromUuidSync(uuid));
  // the newest echo lingers; the others fade
  const last = fromUuidSync(echoes.at(-1) ?? "");
  for (const uuid of echoes.slice(0, -1)) await removeEcho(uuid);
  if (last?.object) await DAE.renameToken(last.object, `Lingering echo of ${token?.name ?? actor.name}`);
  if (last) await say(actor, `${actor.name}'s last echo lingers, silent, where they last stood.`);
  const shroud = shroudOf(actor);
  if (shroud && !shroud.disabled) await updateEffect(actor, shroud, { disabled: true });
  const potion = actor.items.get(macroItem?.id);
  if (potion) await potion.delete();
  return;
}

if (args[0]?.tag === "TargetOnUse" && pass === "isAttacked" && !isEcho) {
  const me = token?.object ?? token;
  if (!me) return;
  const placed = echoesOf(actor).map(uuid => fromUuidSync(uuid)).filter(e => e?.object)
    .map(e => ({ echo: e, distance: MidiQOL.getDistance(me, e.object) }));
  const near = placed.filter(({ distance }) => distance <= NEAR);
  const reach = placed.filter(({ echo, distance }) => distance > NEAR && MidiQOL.canSee(me, echo.object));
  // one-attack effects (expire once this attack's hits are checked): the miss, and whether Step can be offered
  const changes = [];
  // as mirror image: when the attack would hit, the echoes close by may take it instead
  const attackTotal = workflow?.attackTotal ?? workflow?.attackRoll?.total;
  const ac = actor.system.attributes.ac?.value ?? 10;
  const wouldHit = attackTotal !== undefined && !workflow?.isFumble && (workflow?.isCritical || attackTotal >= ac);
  let struck;
  if (wouldHit && near.length) {
    const roll = await new Roll(`${near.length}d6`).evaluate();
    await roll.toMessage({ speaker: ChatMessage.getSpeaker({ actor }), flavor: `${name}: does an echo take the blow? (3 or higher)` });
    if (roll.dice[0].results.some(r => r.result >= 3)) struck = near[Math.floor(Math.random() * near.length)].echo;
  }
  // the miss is applied after reactions are offered; echoStruck keeps Step from being offered for this attack
  if (struck) changes.push({ key: "flags.midi-qol.grants.attack.fail.all", type: "custom", value: "1" }, { key: "flags.midi-qol.echoStruck", type: "override", value: "1" });
  else if (reach.length) changes.push({ key: "flags.midi-qol.echoStepReady", type: "override", value: "1" });
  if (changes.length) await MidiQOL.socket().executeAsGM("createEffects", { actorUuid: actor.uuid, effects: [{
    name: struck ? "Struck an Echo" : "Echo in Reach", img: macroItem?.img ?? "icons/svg/aura.svg", system: { changes },
    flags: { dae: { specialDuration: ["isAttacked"], showIcon: false } }, transfer: false }] });
  if (struck) {
    await removeEcho(struck.uuid);
    await setEchoes(actor, echoesOf(actor).filter(u => u !== struck.uuid));
    await say(actor, `the blow meant for ${actor.name} strikes one of their echoes, which fades.`);
  }
  return;
}

if (args[0]?.tag === "TargetOnUse" && pass === "isHit") {
  // this is an echo being hit
  const echoToken = args[0].options?.token ?? token;
  const drinker = fromUuidSync(echoToken?.document?.getFlag?.("midi-qol", "echoOf") ?? echoToken?.getFlag?.("midi-qol", "echoOf") ?? "");
  const uuid = echoToken?.document?.uuid ?? echoToken?.uuid;
  await removeEcho(uuid);
  if (drinker) {
    await setEchoes(drinker, echoesOf(drinker).filter(u => u !== uuid));
    await say(drinker, `the blow passes through ${drinker.name}'s echo, which fades.`);
  }
  return;
}

if (args[0]?.tag === "OnUse" && pass === "postActiveEffects" && (workflow?.activity ?? args[0].activity)?.id === "EchoStepStep0000") {
  const me = token?.object ?? token;
  const echoes = echoesOf(actor);
  const inRange = echoes.map(uuid => fromUuidSync(uuid)).filter(e => e?.object && me)
    .map(e => ({ echo: e, distance: MidiQOL.getDistance(me, e.object) }))
    .filter(({ echo, distance }) => distance > NEAR && MidiQOL.canSee(me, echo.object));
  if (!inRange.length) return ui.notifications.warn(`${name}: there is no echo you can see more than ${NEAR} ft away to step to.`);
  let choice = inRange[0];
  if (inRange.length > 1) {
    const picked = await foundry.applications.api.DialogV2.wait({
      window: { title: name },
      content: "<p>Step to which echo?</p>",
      buttons: inRange.sort((a, b) => a.distance - b.distance)
        .map(({ echo, distance }, i) => ({ action: echo.uuid, label: `Echo ${Math.round(distance)} ft away`, default: i === 0 })),
      rejectClose: false
    });
    choice = inRange.find(({ echo }) => echo.uuid === picked) ?? inRange[0];
  }
  await MidiQOL.moveToken(me, choice.echo.object.center, { teleport: true });
  await removeEcho(choice.echo.uuid);
  await setEchoes(actor, echoes.filter(u => u !== choice.echo.uuid));

  // once a round the step costs no reaction: give it back once midi has marked it used
  let free = "";
  const round = game.combat?.started ? `${game.combat.id}.${game.combat.round}` : null;
  const effect = effectOf(actor);
  if (!round || effect?.getFlag("midi-qol", FLAG)?.freeStep !== round) {
    for (let i = 0; i < 30 && !MidiQOL.hasUsedReaction(actor); i++) await new Promise(r => setTimeout(r, 100));
    await MidiQOL.removeReactionUsed(actor, true);
    if (round) await updateEffect(actor, effect, { [`flags.midi-qol.${FLAG}.freeStep`]: round });
    free = " The step costs them nothing.";
  }
  await say(actor, `${actor.name} trades places with an echo; the blow strikes the echo, which bursts against the attacker.${free}`);
}
